-- Province site data: every table that was in province.db, at its final shape.
--
-- Types: identity columns are bigint GENERATED BY DEFAULT AS IDENTITY, so the copy
-- from SQLite can insert the existing ids (it must setval each sequence after).
-- Times are timestamptz, 0/1 flags boolean, JSON jsonb, other integers bigint and
-- REAL double precision. Day strings ('YYYY-MM-DD'), ledger founded_at (it feeds
-- faction_key) and character_roster.created_at (RPCharacters' epoch-seconds string)
-- stay text.
--
-- Rows the site needs at start (patreon_sync_state) are in ../seeds.sql, so
-- the copy from SQLite starts from empty tables.
--
-- Collation: every text column is COLLATE "C", whatever the database default, so
-- comparison and ORDER BY follow code-point order as SQLite's BINARY did, and lower()
-- folds ASCII only, as SQLite's did.

CREATE TABLE codes (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code_hash text COLLATE "C" NOT NULL UNIQUE,
    code_plaintext text COLLATE "C",
    player_uuid text COLLATE "C" NOT NULL,
    scope text COLLATE "C" NOT NULL DEFAULT 'skin',
    realm_id text COLLATE "C" NOT NULL DEFAULT 'main',
    created_at timestamptz NOT NULL,
    expires_at timestamptz NOT NULL,
    redeemed_at timestamptz,
    revoked boolean NOT NULL DEFAULT false,
    minted_via text COLLATE "C"
);

CREATE TABLE submissions (
    id text COLLATE "C" PRIMARY KEY,
    player_uuid text COLLATE "C" NOT NULL,
    code_id bigint NOT NULL,
    kind text COLLATE "C" NOT NULL,
    slug text COLLATE "C" NOT NULL,
    display_name text COLLATE "C" NOT NULL,
    grip_preset text COLLATE "C",
    base_set text COLLATE "C",
    tiers jsonb,
    tier_aliases jsonb,
    helmet_3d_tiers jsonb,
    texture_hash text COLLATE "C",
    add_name boolean NOT NULL DEFAULT false,
    name_colours jsonb,
    name_styles jsonb,
    status text COLLATE "C" NOT NULL,
    deny_reason text COLLATE "C",
    dir_path text COLLATE "C" NOT NULL,
    created_at timestamptz NOT NULL,
    reviewed_at timestamptz,
    applied_at timestamptz,
    discord_message_id text COLLATE "C",
    discord_user_id text COLLATE "C",
    staff boolean NOT NULL DEFAULT false,
    category text COLLATE "C",
    scroll text COLLATE "C",
    tier_scrolls jsonb,
    realm_id text COLLATE "C" NOT NULL DEFAULT 'main',
    tier_sets jsonb,
    FOREIGN KEY (code_id) REFERENCES codes(id)
);

CREATE TABLE sessions (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    token_hash text COLLATE "C" NOT NULL UNIQUE,
    code_id bigint NOT NULL,
    player_uuid text COLLATE "C" NOT NULL,
    expires_at timestamptz NOT NULL,
    created_at timestamptz NOT NULL,
    FOREIGN KEY (code_id) REFERENCES codes(id)
);

CREATE TABLE discord_links (
    player_uuid text COLLATE "C" PRIMARY KEY,
    discord_user_id text COLLATE "C" NOT NULL UNIQUE,
    minecraft_name text COLLATE "C",
    discord_username text COLLATE "C",
    linked_at timestamptz NOT NULL,
    left_guild_at timestamptz,
    grace_until timestamptz,
    -- Their nickname in the TFMC Discord server, if any; discord_username is the account handle.
    discord_nickname text COLLATE "C",
    -- How the link was proved: 'code' (in-game code) or 'microsoft'. NULL for links made before this was kept.
    link_method text COLLATE "C"
);

CREATE TABLE discord_link_codes (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code_hash text COLLATE "C" NOT NULL UNIQUE,
    player_uuid text COLLATE "C" NOT NULL,
    minecraft_name text COLLATE "C",
    created_at timestamptz NOT NULL,
    expires_at timestamptz NOT NULL,
    used_at timestamptz
);

-- One-time war declare codes. Staff mint one in Discord bound to an attacker,
-- a defender and a war goal; the plugin validates it, then redeems it only once
-- the war actually exists. No plaintext is stored: staff see the code once.
CREATE TABLE war_declare_codes (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code_hash text COLLATE "C" NOT NULL UNIQUE,
    realm_id text COLLATE "C" NOT NULL DEFAULT 'main',
    attacker_faction_id text COLLATE "C" NOT NULL,
    defender_faction_id text COLLATE "C" NOT NULL,
    goal text COLLATE "C" NOT NULL,
    created_by_discord_id text COLLATE "C",
    created_at timestamptz NOT NULL,
    expires_at timestamptz NOT NULL,
    redeemed_at timestamptz,
    redeemed_war_id text COLLATE "C",
    revoked boolean NOT NULL DEFAULT false
);

CREATE TABLE skin_notifications (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    type text COLLATE "C" NOT NULL,
    submission_id text COLLATE "C" NOT NULL,
    discord_user_id text COLLATE "C" NOT NULL,
    payload jsonb NOT NULL,
    created_at timestamptz NOT NULL,
    delivered_at timestamptz
);

CREATE TABLE plugin_notices (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    type text COLLATE "C" NOT NULL,
    player_uuid text COLLATE "C" NOT NULL,
    payload jsonb NOT NULL,
    created_at timestamptz NOT NULL,
    delivered_at timestamptz
);

CREATE INDEX idx_submissions_status ON submissions(status);

CREATE INDEX idx_submissions_slug ON submissions(slug);

CREATE INDEX idx_war_declare_codes_outstanding
    ON war_declare_codes(realm_id, redeemed_at, revoked);

CREATE INDEX idx_skin_notifications_undelivered
    ON skin_notifications(delivered_at, created_at);

CREATE INDEX idx_plugin_notices_undelivered
    ON plugin_notices(delivered_at, created_at);

CREATE TABLE player_warnings (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    player_uuid text COLLATE "C" NOT NULL,
    staff_uuid text COLLATE "C",
    staff_name text COLLATE "C",
    reason text COLLATE "C" NOT NULL,
    created_at timestamptz NOT NULL
);

CREATE TABLE moderation_notifications (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    type text COLLATE "C" NOT NULL,
    discord_user_id text COLLATE "C" NOT NULL,
    player_uuid text COLLATE "C",
    payload jsonb NOT NULL,
    created_at timestamptz NOT NULL,
    delivered_at timestamptz
);

CREATE INDEX idx_player_warnings_uuid
    ON player_warnings(player_uuid, created_at);

CREATE INDEX idx_moderation_notifications_undelivered
    ON moderation_notifications(delivered_at, created_at);

CREATE TABLE armourshop_catalog (
    id integer PRIMARY KEY CHECK (id = 1),
    payload jsonb NOT NULL,
    updated_at timestamptz NOT NULL
);

CREATE TABLE lore_item_customisations (
    player_uuid text COLLATE "C" NOT NULL,
    character_id text COLLATE "C" NOT NULL,
    kit_key text COLLATE "C" NOT NULL,
    kit_id text COLLATE "C",
    name_colours jsonb,
    name_styles jsonb,
    display_name text COLLATE "C" NOT NULL DEFAULT '',
    lore_json jsonb NOT NULL DEFAULT '[]',
    existing_skin_id text COLLATE "C",
    submission_id text COLLATE "C",
    state text COLLATE "C" NOT NULL DEFAULT 'draft',
    skin_slug text COLLATE "C",
    ready_at timestamptz,
    applied_at timestamptz,
    deny_reason text COLLATE "C",
    updated_at timestamptz NOT NULL,
    realm_id text COLLATE "C" NOT NULL DEFAULT 'main',
    PRIMARY KEY (player_uuid, character_id, kit_key)
);

CREATE TABLE character_wardrobe_slots (
    player_uuid text COLLATE "C" NOT NULL,
    character_id text COLLATE "C" NOT NULL,
    slot text COLLATE "C" NOT NULL,
    png_relpath text COLLATE "C",
    texture_value text COLLATE "C",
    texture_signature text COLLATE "C",
    model text COLLATE "C",
    display_name text COLLATE "C",
    apply_pending boolean NOT NULL DEFAULT false,
    updated_at timestamptz NOT NULL,
    PRIMARY KEY (player_uuid, character_id, slot)
);

CREATE TABLE character_create_wardrobe (
    create_id text COLLATE "C" NOT NULL,
    slot text COLLATE "C" NOT NULL,
    png_relpath text COLLATE "C",
    texture_value text COLLATE "C",
    texture_signature text COLLATE "C",
    model text COLLATE "C",
    display_name text COLLATE "C",
    updated_at timestamptz NOT NULL,
    PRIMARY KEY (create_id, slot)
);

CREATE TABLE drink_submissions (
    id text COLLATE "C" PRIMARY KEY,
    player_uuid text COLLATE "C" NOT NULL,
    code_id bigint NOT NULL,
    slug text COLLATE "C" NOT NULL,
    display_name text COLLATE "C" NOT NULL,
    recipe_json jsonb NOT NULL,
    status text COLLATE "C" NOT NULL,
    deny_reason text COLLATE "C",
    texture_id text COLLATE "C",
    new_texture boolean NOT NULL DEFAULT false,
    dir_path text COLLATE "C" NOT NULL,
    discord_user_id text COLLATE "C",
    created_at timestamptz NOT NULL,
    reviewed_at timestamptz,
    applied_at timestamptz,
    realm_id text COLLATE "C" NOT NULL DEFAULT 'main',
    FOREIGN KEY (code_id) REFERENCES codes(id)
);

CREATE TABLE drink_textures (
    id text COLLATE "C" PRIMARY KEY,
    owner_uuid text COLLATE "C" NOT NULL,
    cmd bigint,
    ia_item_id text COLLATE "C",
    png_path text COLLATE "C" NOT NULL,
    refcount bigint NOT NULL DEFAULT 0,
    created_at timestamptz NOT NULL
);

CREATE TABLE drink_catalog (
    id integer PRIMARY KEY CHECK (id = 1),
    payload jsonb NOT NULL,
    updated_at timestamptz NOT NULL
);

CREATE TABLE rpc_player_meta (
    player_uuid text COLLATE "C" NOT NULL,
    realm_id text COLLATE "C" NOT NULL DEFAULT 'main',
    name_colour_stops bigint NOT NULL DEFAULT 0,
    allow_drink_texture boolean NOT NULL DEFAULT false,
    allow_drink_message boolean NOT NULL DEFAULT false,
    max_alive_characters bigint,
    wardrobe_skin_slots bigint NOT NULL DEFAULT 1,
    max_3d_pair_bytes bigint NOT NULL DEFAULT 0,
    skin_token_cooldown_days bigint NOT NULL DEFAULT -1,
    skin_kinds_json jsonb NOT NULL DEFAULT '[]',
    allow_armor_3d_helmet boolean NOT NULL DEFAULT false,
    permission_flags_json jsonb NOT NULL DEFAULT '{}',
    updated_at timestamptz NOT NULL,
    PRIMARY KEY (player_uuid, realm_id)
);

CREATE TABLE drink_notifications (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    type text COLLATE "C" NOT NULL,
    submission_id text COLLATE "C" NOT NULL,
    discord_user_id text COLLATE "C" NOT NULL,
    payload jsonb NOT NULL,
    created_at timestamptz NOT NULL,
    delivered_at timestamptz
);

CREATE TABLE cosmetic_mint_resets (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    player_uuid text COLLATE "C" NOT NULL,
    reset_at timestamptz NOT NULL,
    staff_uuid text COLLATE "C"
);

CREATE INDEX idx_drink_submissions_status
    ON drink_submissions(status);

CREATE INDEX idx_drink_submissions_slug
    ON drink_submissions(slug);

CREATE INDEX idx_drink_textures_owner
    ON drink_textures(owner_uuid);

CREATE INDEX idx_drink_notifications_undelivered
    ON drink_notifications(delivered_at, created_at);

CREATE INDEX idx_cosmetic_mint_resets_player
    ON cosmetic_mint_resets(player_uuid);

CREATE TABLE map_chronicle_snapshots (
    map_id text COLLATE "C" NOT NULL,
    day text COLLATE "C" NOT NULL,
    realm_id text COLLATE "C" NOT NULL DEFAULT 'main',
    captured_at bigint NOT NULL,
    bytes bigint NOT NULL,
    geometry_version text COLLATE "C",
    manifest jsonb NOT NULL,
    PRIMARY KEY (map_id, day)
);

CREATE TABLE map_chronicle_snapshots_archive (
    map_id text COLLATE "C" NOT NULL,
    day text COLLATE "C" NOT NULL,
    realm_id text COLLATE "C" NOT NULL DEFAULT 'main',
    captured_at bigint NOT NULL,
    bytes bigint NOT NULL,
    geometry_version text COLLATE "C",
    manifest jsonb NOT NULL,
    archived_at bigint NOT NULL,
    PRIMARY KEY (map_id, day, archived_at)
);

CREATE INDEX idx_map_chronicle_snapshots_archive_map
    ON map_chronicle_snapshots_archive(map_id, archived_at);

-- Audit trail for staff-triggered chronicle wipes (and their restores).
-- `wiped_at` is the archive stamp the wipe used: it is both the audit clock and
-- the key that ties this row to its `map_chronicle_snapshots_archive` rows and
-- to the `chronicle.bak.<wiped_at>` directory, so a restore can find both.
CREATE TABLE map_chronicle_wipes (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    map_id text COLLATE "C" NOT NULL,
    wiped_at bigint NOT NULL,
    wiped_by text COLLATE "C" NOT NULL,
    day_count bigint NOT NULL DEFAULT 0,
    -- NULL when the wipe found index rows but no directory to set aside.
    backup_path text COLLATE "C",
    reason text COLLATE "C" NOT NULL,
    restored_at bigint,
    restored_by text COLLATE "C"
);

CREATE INDEX idx_map_chronicle_wipes_map
    ON map_chronicle_wipes(map_id, wiped_at);

-- Economy ledger (SimpleFactions `chronicle` upload mode). Partitioned on the
-- captured_at UTC date; `server_day` is the in-game clock and drifts, so it is
-- carried alongside but never used as a key.
CREATE TABLE map_ledger_days (
    map_id text COLLATE "C" NOT NULL,
    day text COLLATE "C" NOT NULL,
    captured_at timestamptz NOT NULL,
    captured_at_ts bigint NOT NULL,
    server_day bigint,
    day_progress_seconds bigint,
    -- False when this day's canonical row is only the latest partial snapshot.
    complete boolean NOT NULL DEFAULT false,
    schema_version bigint NOT NULL DEFAULT 0,
    faction_count bigint NOT NULL DEFAULT 0,
    guild_count bigint NOT NULL DEFAULT 0,
    globals jsonb NOT NULL,
    PRIMARY KEY (map_id, day)
);

-- Faction identity is (id, founded_at) hashed into faction_key: ids derive from
-- the faction name and are reused after deletion.
CREATE TABLE map_ledger_factions (
    map_id text COLLATE "C" NOT NULL,
    faction_key text COLLATE "C" NOT NULL,
    faction_id text COLLATE "C" NOT NULL,
    founded_at text COLLATE "C" NOT NULL,
    first_seen_day text COLLATE "C" NOT NULL,
    first_seen_at timestamptz NOT NULL,
    last_seen_day text COLLATE "C" NOT NULL,
    last_seen_at timestamptz NOT NULL,
    last_name text COLLATE "C",
    last_rgb text COLLATE "C",
    deleted_day text COLLATE "C",
    deleted_at timestamptz,
    PRIMARY KEY (map_id, faction_key)
);

CREATE TABLE map_ledger_faction_days (
    map_id text COLLATE "C" NOT NULL,
    day text COLLATE "C" NOT NULL,
    faction_key text COLLATE "C" NOT NULL,
    faction_id text COLLATE "C" NOT NULL,
    founded_at text COLLATE "C" NOT NULL,
    name text COLLATE "C",
    rgb text COLLATE "C",
    overlord text COLLATE "C",
    wealth double precision,
    bank double precision,
    vassal_wealth double precision,
    net_income double precision,
    inflation_delta double precision,
    trade_power double precision,
    prestige double precision,
    "rank" text COLLATE "C",
    rank_level bigint,
    rank_up_at double precision,
    rank_down_at double precision,
    prestige_position bigint,
    wealth_position bigint,
    provinces bigint,
    realm_size bigint,
    tier text COLLATE "C",
    tier_index bigint,
    highest_title text COLLATE "C",
    members bigint,
    members_with_vassals bigint,
    settlements bigint,
    population bigint,
    installations bigint,
    forts bigint,
    wealth_breakdown jsonb NOT NULL DEFAULT '{}',
    prestige_breakdown jsonb NOT NULL DEFAULT '{}',
    subjects jsonb NOT NULL DEFAULT '[]',
    wars jsonb NOT NULL DEFAULT '[]',
    PRIMARY KEY (map_id, day, faction_key)
);

-- No founded_at in the guild payload, so guild identity is weak: a deleted and
-- recreated guild reads as continuous. Documented limitation, no guild registry.
CREATE TABLE map_ledger_guild_days (
    map_id text COLLATE "C" NOT NULL,
    day text COLLATE "C" NOT NULL,
    guild_id text COLLATE "C" NOT NULL,
    faction_id text COLLATE "C",
    name text COLLATE "C",
    type text COLLATE "C",
    wealth double precision,
    bank double precision,
    expansions bigint,
    trade_power double precision,
    credit_score double precision,
    size bigint,
    PRIMARY KEY (map_id, day, guild_id)
);

CREATE INDEX idx_map_ledger_factions_id
    ON map_ledger_factions(map_id, faction_id);

CREATE INDEX idx_map_ledger_faction_days_key
    ON map_ledger_faction_days(map_id, faction_key, day);

-- Patreon lives beside discord_links; link tombstones retain relink history.
CREATE TABLE patreon_members (
    member_id text COLLATE "C" PRIMARY KEY,
    patreon_user_id text COLLATE "C" NOT NULL UNIQUE,
    data_json jsonb NOT NULL,
    last_tier text COLLATE "C",
    declined_since timestamptz,
    updated_at timestamptz NOT NULL
);

CREATE TABLE patreon_links (
    patreon_user_id text COLLATE "C" PRIMARY KEY,
    discord_user_id text COLLATE "C",
    player_uuid text COLLATE "C",
    method text COLLATE "C" NOT NULL,
    active boolean NOT NULL DEFAULT true,
    linked_at timestamptz NOT NULL,
    person_changed_at timestamptz NOT NULL
);

CREATE UNIQUE INDEX idx_patreon_link_discord
    ON patreon_links(discord_user_id) WHERE active;

CREATE UNIQUE INDEX idx_patreon_link_uuid
    ON patreon_links(player_uuid) WHERE active;

CREATE TABLE patreon_tokens (
    id integer PRIMARY KEY CHECK (id = 1),
    access_token text COLLATE "C" NOT NULL,
    refresh_token text COLLATE "C" NOT NULL,
    expires_at timestamptz NOT NULL
);

CREATE TABLE patreon_leases (
    name text COLLATE "C" PRIMARY KEY,
    owner text COLLATE "C" NOT NULL,
    expires_at timestamptz NOT NULL
);

CREATE TABLE patreon_sync_state (
    id integer PRIMARY KEY CHECK (id = 1),
    last_sync_at timestamptz,
    last_sync_ok boolean,
    consecutive_failures bigint NOT NULL DEFAULT 0,
    brake_held boolean NOT NULL DEFAULT false
);

CREATE TABLE patreon_applied (
    target text COLLATE "C" NOT NULL,
    subject text COLLATE "C" NOT NULL,
    tiers_json jsonb NOT NULL DEFAULT '[]',
    ever_granted boolean NOT NULL DEFAULT false,
    dm_generation bigint NOT NULL DEFAULT 0,
    PRIMARY KEY (target, subject)
);

CREATE TABLE patreon_desired (
    target text COLLATE "C" NOT NULL,
    subject text COLLATE "C" NOT NULL,
    tier_key text COLLATE "C",
    grace_until timestamptz,
    dm text COLLATE "C",
    generation bigint NOT NULL DEFAULT 1,
    link_event text COLLATE "C",
    PRIMARY KEY (target, subject)
);

CREATE TABLE patreon_changes (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    target text COLLATE "C" NOT NULL,
    subject text COLLATE "C" NOT NULL,
    add_tier text COLLATE "C",
    remove_json jsonb NOT NULL,
    dm text COLLATE "C",
    grace_until timestamptz,
    generation bigint NOT NULL,
    created_at timestamptz NOT NULL,
    dispatched_at timestamptz,
    acked_at timestamptz,
    cancelled_at timestamptz,
    dm_suppressed boolean NOT NULL DEFAULT false
);

CREATE INDEX idx_patreon_changes_pending
    ON patreon_changes(target, acked_at, cancelled_at, subject);

CREATE TABLE patreon_alerts (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    kind text COLLATE "C" NOT NULL,
    message text COLLATE "C" NOT NULL,
    created_at timestamptz NOT NULL,
    acked_at timestamptz
);
CREATE UNIQUE INDEX idx_patreon_alerts_open
    ON patreon_alerts(kind) WHERE acked_at IS NULL;

CREATE TABLE patreon_brake_approvals (
    target text COLLATE "C" NOT NULL,
    subject text COLLATE "C" NOT NULL,
    generation bigint NOT NULL,
    PRIMARY KEY (target, subject)
);

-- OAuth state is stored hashed, single-use, and bound to the subject that started it.
CREATE TABLE patreon_oauth_states (
    state_hash text COLLATE "C" PRIMARY KEY,
    discord_user_id text COLLATE "C",
    player_uuid text COLLATE "C",
    target_kind text COLLATE "C",
    target_name text COLLATE "C",
    expires_at timestamptz NOT NULL,
    used_at timestamptz,
    CHECK ((discord_user_id IS NULL) <> (player_uuid IS NULL))
);

-- Consent alone grants nothing; the patron must explicitly confirm this target.
CREATE TABLE patreon_pending_links (
    token_hash text COLLATE "C" PRIMARY KEY,
    patreon_user_id text COLLATE "C" NOT NULL,
    patreon_name text COLLATE "C" NOT NULL,
    discord_user_id text COLLATE "C",
    player_uuid text COLLATE "C",
    target_kind text COLLATE "C" NOT NULL CHECK (target_kind IN ('discord', 'minecraft')),
    target_name text COLLATE "C" NOT NULL,
    expires_at timestamptz NOT NULL,
    used_at timestamptz,
    CHECK ((discord_user_id IS NULL) <> (player_uuid IS NULL))
);

-- Webhook member ids waiting for an out-of-band refresh (kept if the sync lease is busy).
CREATE TABLE patreon_webhook_members (
    member_id text COLLATE "C" PRIMARY KEY,
    recorded_at timestamptz NOT NULL
);

CREATE TABLE creation_catalog (
    id integer PRIMARY KEY CHECK (id = 1),
    payload jsonb NOT NULL,
    updated_at timestamptz NOT NULL
);

CREATE TABLE character_creates (
    id text COLLATE "C" PRIMARY KEY,
    player_uuid text COLLATE "C" NOT NULL,
    client_request_id text COLLATE "C",
    payload jsonb NOT NULL,
    status text COLLATE "C" NOT NULL,
    character_id text COLLATE "C",
    error text COLLATE "C",
    created_at timestamptz NOT NULL,
    applied_at timestamptz,
    realm_id text COLLATE "C" NOT NULL DEFAULT 'main',
    wardrobe_active_slot text COLLATE "C",
    held_until timestamptz
);

CREATE TABLE character_roster (
    player_uuid text COLLATE "C" NOT NULL,
    realm_id text COLLATE "C" NOT NULL DEFAULT 'main',
    character_id text COLLATE "C" NOT NULL,
    name text COLLATE "C" NOT NULL,
    status text COLLATE "C" NOT NULL,
    race text COLLATE "C",
    class text COLLATE "C",
    created_at text COLLATE "C",
    updated_at timestamptz NOT NULL,
    kit_status text COLLATE "C",
    kit_statuses_json jsonb,
    sheet_json jsonb,
    wardrobe_active_slot text COLLATE "C",
    died_at timestamptz,
    death_id text COLLATE "C",
    will_heir_id text COLLATE "C",
    will_heir_name text COLLATE "C",
    will_revision bigint,
    PRIMARY KEY (player_uuid, realm_id, character_id)
);

-- One row per death, from RPCharacters' roster pushes. A push never deletes these.
CREATE TABLE character_estates (
    realm_id text COLLATE "C" NOT NULL,
    death_id text COLLATE "C" NOT NULL,
    player_uuid text COLLATE "C" NOT NULL,
    character_id text COLLATE "C" NOT NULL,
    status text COLLATE "C" NOT NULL,
    revision bigint NOT NULL,
    source_updated_at timestamptz,
    payload jsonb NOT NULL,
    received_at timestamptz NOT NULL,
    PRIMARY KEY (realm_id, death_id)
);

CREATE INDEX idx_character_estates_character
    ON character_estates(realm_id, character_id);

-- Will changes made on Profile, pulled and acknowledged by RPCharacters.
CREATE TABLE will_requests (
    id text COLLATE "C" PRIMARY KEY,
    realm_id text COLLATE "C" NOT NULL,
    character_id text COLLATE "C" NOT NULL,
    account_uuid text COLLATE "C" NOT NULL,
    heir_character_id text COLLATE "C",
    base_revision bigint NOT NULL,
    created_at timestamptz NOT NULL,
    status text COLLATE "C" NOT NULL CHECK (status IN ('pending', 'acked', 'replaced')),
    result text COLLATE "C",
    acked_at timestamptz
);

CREATE INDEX idx_will_requests_pending
    ON will_requests(realm_id, status, created_at);

-- At most one pending request per character.
CREATE UNIQUE INDEX idx_will_requests_one_pending
    ON will_requests(realm_id, character_id) WHERE status = 'pending';

CREATE INDEX idx_will_requests_character
    ON will_requests(realm_id, character_id, created_at);

CREATE TABLE character_player_meta (
    player_uuid text COLLATE "C" PRIMARY KEY,
    -- Age-only upserts need to leave the character limit unset.
    max_alive_characters bigint,
    eighteen boolean,
    real_age_set boolean NOT NULL DEFAULT false,
    account_created_at_epoch bigint,
    name_colour_stops bigint,
    updated_at timestamptz NOT NULL,
    kit_cooldown_seconds_remaining bigint,
    kit_cooldown_hours bigint,
    kit_cooldowns_json jsonb,
    wardrobe_skin_slots bigint
);

CREATE INDEX idx_discord_links_grace
    ON discord_links(grace_until);

CREATE INDEX idx_submissions_texture_hash
    ON submissions(player_uuid, texture_hash);

CREATE INDEX idx_character_creates_realm_status
    ON character_creates(realm_id, status);

CREATE UNIQUE INDEX idx_character_creates_client_req
    ON character_creates(player_uuid, client_request_id)
    WHERE client_request_id IS NOT NULL AND TRIM(client_request_id) != '';

CREATE INDEX idx_character_creates_pending
    ON character_creates(status, created_at);

CREATE INDEX idx_lore_item_customisations_realm_state
    ON lore_item_customisations(realm_id, state);

CREATE INDEX idx_submissions_realm_apply
    ON submissions(realm_id, status, applied_at);

CREATE INDEX idx_drink_submissions_realm_apply
    ON drink_submissions(realm_id, status, applied_at);

-- Website accounts. Discord is the sign-in provider; the Minecraft account is
-- the discord_links row for the same discord_user_id, so links made through
-- the Discord bot appear on the website without another step.
CREATE TABLE users (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    discord_user_id text COLLATE "C" NOT NULL UNIQUE,
    discord_username text COLLATE "C",
    discord_global_name text COLLATE "C",
    discord_avatar text COLLATE "C",
    created_at timestamptz NOT NULL,
    updated_at timestamptz NOT NULL,
    last_login_at timestamptz NOT NULL,
    -- Website staff role.
    role text COLLATE "C" NOT NULL DEFAULT 'player' CHECK (role IN ('player', 'mod', 'admin', 'root')),
    -- True for an account made so an admin can view the site as a player who has
    -- never signed in (src/auth/view_as.py). Deleted once its views end;
    -- signing in makes it a real account.
    placeholder boolean NOT NULL DEFAULT false
);

CREATE INDEX idx_users_role ON users(role);

-- Cookie sessions for users. Separate from `sessions`, which belong to
-- in-game codes and carry a scope and realm. guild_member records the TFMC
-- Discord membership seen at sign-in; linking requires a recent check.
-- acting_user_id is the admin viewing the site as this user (view only,
-- src/auth/view_as.py).
CREATE TABLE user_sessions (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    token_hash text COLLATE "C" NOT NULL UNIQUE,
    user_id bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    guild_member boolean NOT NULL DEFAULT false,
    guild_checked_at timestamptz,
    created_at timestamptz NOT NULL,
    expires_at timestamptz NOT NULL,
    acting_user_id bigint REFERENCES users(id) ON DELETE CASCADE
);

CREATE INDEX idx_user_sessions_user ON user_sessions(user_id);
CREATE INDEX idx_user_sessions_acting ON user_sessions(acting_user_id);

CREATE INDEX idx_user_sessions_expiry ON user_sessions(expires_at);

-- Single-use Discord OAuth states. The browser also holds the state in a
-- cookie, so a callback only completes in the browser that started it.
CREATE TABLE discord_oauth_states (
    state_hash text COLLATE "C" PRIMARY KEY,
    return_to text COLLATE "C" NOT NULL,
    expires_at timestamptz NOT NULL
);

CREATE INDEX idx_discord_link_codes_player ON discord_link_codes(player_uuid);

-- Single-use tickets that carry a dev sign-in to a branch preview, which
-- redeems one with dev within two minutes (src/auth/preview_sign_in.py).
CREATE TABLE preview_sign_in_tickets (
    ticket_hash text COLLATE "C" PRIMARY KEY,
    site text COLLATE "C" NOT NULL,
    user_id bigint NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    guild_member boolean NOT NULL,
    guild_checked_at timestamptz,
    expires_at timestamptz NOT NULL
);

-- Single-use Microsoft link attempts, tied to the site session that started
-- them. The callback marks a row used and deletes it once done; unlinking
-- deletes the user's rows, which cancels any attempt still in flight. A new
-- attempt replaces the user's last one (INSERT ... ON CONFLICT (user_id)).
CREATE TABLE microsoft_link_states (
    state_hash text COLLATE "C" PRIMARY KEY,
    session_id bigint NOT NULL,
    user_id bigint NOT NULL UNIQUE,
    code_verifier text COLLATE "C" NOT NULL,
    expires_at timestamptz NOT NULL,
    used_at timestamptz
);

-- Append-only record of staff actions on website accounts, including refused
-- attempts; the triggers below refuse UPDATE, DELETE and TRUNCATE. No foreign
-- keys: rows outlive the accounts they mention, so each row keeps the names it
-- was written with.
CREATE TABLE admin_audit (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at timestamptz NOT NULL,
    actor_type text COLLATE "C" NOT NULL CHECK (actor_type IN ('user', 'system')),
    actor_user_id bigint,
    actor_discord_id text COLLATE "C",
    actor_name text COLLATE "C",
    actor_role text COLLATE "C",
    action text COLLATE "C" NOT NULL,
    outcome text COLLATE "C" NOT NULL,
    target_user_id bigint,
    target_discord_id text COLLATE "C",
    target_name text COLLATE "C",
    reason text COLLATE "C",
    detail_json jsonb NOT NULL DEFAULT '{}'
);

CREATE INDEX idx_admin_audit_target ON admin_audit(target_user_id, id);

CREATE INDEX idx_admin_audit_actor ON admin_audit(actor_user_id, id);

CREATE FUNCTION admin_audit_append_only() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'admin_audit is append-only';
END;
$$;

-- An upsert that meets an existing id fires the UPDATE trigger too.
CREATE TRIGGER admin_audit_no_change BEFORE UPDATE OR DELETE ON admin_audit
    FOR EACH ROW EXECUTE FUNCTION admin_audit_append_only();

-- Row triggers do not fire on TRUNCATE.
CREATE TRIGGER admin_audit_no_truncate BEFORE TRUNCATE ON admin_audit
    FOR EACH STATEMENT EXECUTE FUNCTION admin_audit_append_only();

-- LuckPerms mirror for the staff panel. The TFMCWeb bridge publishes a whole
-- snapshot, which replaces these tables in one transaction; see
-- src/luckperms/README.md. Contexts are canonical JSON ({} when global) and
-- expiry is unix seconds, 0 when permanent.
CREATE TABLE lp_state (
    id integer PRIMARY KEY CHECK (id = 1),
    server text COLLATE "C",
    hash text COLLATE "C",
    generated_at bigint,
    -- Newest bridge revision applied: a snapshot's, or a change result's.
    revision bigint,
    received_at timestamptz,
    -- Last time the bridge confirmed the snapshot is still current.
    checked_at timestamptz,
    -- Last time an applying bridge asked for changes.
    polled_at timestamptz
);

CREATE TABLE lp_groups (
    name text COLLATE "C" PRIMARY KEY,
    display_name text COLLATE "C",
    weight bigint
);

CREATE TABLE lp_group_nodes (
    group_name text COLLATE "C" NOT NULL,
    key text COLLATE "C" NOT NULL,
    value boolean NOT NULL,
    contexts jsonb NOT NULL,
    expiry bigint NOT NULL
);

CREATE INDEX idx_lp_group_nodes_group ON lp_group_nodes(group_name);

CREATE TABLE lp_tracks (
    name text COLLATE "C" PRIMARY KEY,
    groups_json jsonb NOT NULL
);

CREATE TABLE lp_users (
    uuid text COLLATE "C" PRIMARY KEY,
    name text COLLATE "C"
);

CREATE INDEX idx_lp_users_name ON lp_users(lower(name));

CREATE TABLE lp_user_nodes (
    uuid text COLLATE "C" NOT NULL,
    key text COLLATE "C" NOT NULL,
    value boolean NOT NULL,
    contexts jsonb NOT NULL,
    expiry bigint NOT NULL
);

CREATE INDEX idx_lp_user_nodes_uuid ON lp_user_nodes(uuid);

CREATE INDEX idx_lp_user_nodes_key ON lp_user_nodes(key);

-- The server's commands and each group's access, as TFMCWeb last published
-- them for the Commands tab; see src/luckperms/commands.py.
CREATE TABLE lp_commands (
    id integer PRIMARY KEY CHECK (id = 1),
    server text COLLATE "C",
    hash text COLLATE "C",
    generated_at bigint,
    received_at timestamptz,
    payload jsonb NOT NULL
);

-- Changes staff queued for the bridge. Rows are kept as the change history.
CREATE TABLE lp_changes (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    created_at timestamptz NOT NULL,
    actor_user_id bigint NOT NULL,
    actor_name text COLLATE "C",
    actor_role text COLLATE "C",
    actor_minecraft_uuid text COLLATE "C",
    target_type text COLLATE "C" NOT NULL CHECK (target_type IN ('user', 'group', 'track')),
    target text COLLATE "C" NOT NULL,
    target_name text COLLATE "C",
    description text COLLATE "C" NOT NULL,
    ops_json jsonb NOT NULL,
    reason text COLLATE "C" NOT NULL,
    status text COLLATE "C" NOT NULL DEFAULT 'pending'
        CHECK (status IN ('pending', 'sent', 'applied', 'failed', 'expired', 'unknown')),
    attempts bigint NOT NULL DEFAULT 0,
    sent_at timestamptz,
    finished_at timestamptz,
    error text COLLATE "C"
);

CREATE INDEX idx_lp_changes_status ON lp_changes(status, id);

CREATE INDEX idx_lp_changes_target ON lp_changes(target_type, target, id);

-- At most one open change per target.
CREATE UNIQUE INDEX idx_lp_changes_one_open
    ON lp_changes(target_type, target) WHERE status IN ('pending', 'sent');

-- Reports players send from /diagnostic, looked up by code; kept 30 days.
CREATE TABLE diagnostic_reports (
    code text COLLATE "C" PRIMARY KEY,
    created_at timestamptz NOT NULL,
    user_id bigint,
    discord_name text COLLATE "C",
    minecraft_name text COLLATE "C",
    country text COLLATE "C",
    worst text COLLATE "C" NOT NULL CHECK (worst IN ('fail', 'warn', 'info', 'ok')),
    summary text COLLATE "C" NOT NULL,
    report_json jsonb NOT NULL
);

CREATE INDEX idx_diagnostic_reports_created ON diagnostic_reports(created_at);
